If(
    IsBlank(ThisItem.Gate),
    Blank(),
    With(
        {
            varTracking: If(
                IsBlank(ThisItem.State) || IsBlank(ThisItem.State.ID),
                Blank(),
                LookUp(
                    'Project State Trackings',
                    'Project State Tracking' = GUID(ThisItem.State.ID)
                )
            ),
            varDefaultApprovalAppSettings: LookUp(
                'Project Default Approvals',
                'Project Default Approvals' = ThisItem.Gate
            )
        },
        With(
            {
                varLastTriggeredText: Coalesce(
                    varTracking.'Last Triggered Approval Personas',
                    ""
                )
            },
            With(
                {
                    varUseLastTriggeredPersonas: And(
                        Not(IsBlank(Trim(varLastTriggeredText))),
                        Or(
                            Not(IsBlank(varTracking.FlowRunId)),
                            Not(IsBlank(varTracking.FlowApprovalId)),
                            varTracking.'Approval Cluster State' in [
                                'Approval Cluster States'.Completed,
                                'Approval Cluster States'.Rejected,
                                'Approval Cluster States'.'Request canceled',
                                'Approval Cluster States'.Canceling,
                                'Approval Cluster States'.Abandoned,
                                'Approval Cluster States'.'Inactive/ On-hold'
                            ]
                        )
                    )
                },
                If(
                    varUseLastTriggeredPersonas,
                    With(
                        {
                            varLastTriggeredApproval: Table(
                                ParseJSON(varLastTriggeredText)
                            )
                        },
                        With(
                            {
                                varPortfolioManager: Coalesce(
                                    Concat(
                                        ForAll(
                                            varLastTriggeredApproval,
                                            {Mail: Text(Value.PortfolioManager)}
                                        ),
                                        Mail,
                                        Char(13)
                                    ),
                                    "None"
                                ),
                                varDefaultApprovers: Coalesce(
                                    Concat(
                                        ForAll(
                                            varLastTriggeredApproval,
                                            {Mail: Text(Value.Approvers)}
                                        ),
                                        Mail,
                                        Char(13)
                                    ),
                                    "None"
                                ),
                                varDefaultContributors: Coalesce(
                                    Concat(
                                        ForAll(
                                            varLastTriggeredApproval,
                                            {Mail: Text(Value.Contributors)}
                                        ),
                                        Mail,
                                        Char(13)
                                    ),
                                    "None"
                                ),
                                varDefaultNotifications: Coalesce(
                                    Concat(
                                        ForAll(
                                            varLastTriggeredApproval,
                                            {Mail: Text(Value.Notifications)}
                                        ),
                                        Mail,
                                        Char(13)
                                    ),
                                    "None"
                                )
                            },
                            Switch(
                                varTracking.'Last Triggered Approval Mode',
                                'Approval Mode'.'Formal Approval',
                                $"Portfolio Manager:{Char(13)}{varPortfolioManager}{Char(13)}{Char(13)}Contributors:{Char(13)}{varDefaultContributors}{Char(13)}{Char(13)}Approvers:{Char(13)}{varDefaultApprovers}{Char(13)}{Char(13)}Notifications:{Char(13)}{varDefaultNotifications}",
                                'Approval Mode'.'Local Approval',
                                $"Approvers:{Char(13)}{varDefaultApprovers}{Char(13)}{Char(13)}Notifications:{Char(13)}{varDefaultNotifications}",
                                'Approval Mode'.'Only Notifications',
                                $"Notifications:{Char(13)}{varDefaultNotifications}",
                                Blank()
                            )
                        )
                    ),
                    With(
                        {
                            varPortfolioManager: Coalesce(
                                varDefaultApprovalAppSettings.'Portfolio Manager'.Mail,
                                "None"
                            ),
                            varDefaultApprovers: Coalesce(
                                Concat(
                                    ForAll(
                                        Table(ParseJSON(varDefaultApprovalAppSettings.'Default Approvals')),
                                        {Mail: Text(Value.PersonaRole)}
                                    ),
                                    Mail,
                                    Char(13)
                                ),
                                "None"
                            ),
                            varDefaultContributors: Coalesce(
                                Concat(
                                    ForAll(
                                        Table(ParseJSON(varDefaultApprovalAppSettings.'Default Contributors')),
                                        {Mail: Text(Value.PersonaRole)}
                                    ),
                                    Mail,
                                    Char(13)
                                ),
                                "None"
                            ),
                            varDefaultNotifications: Coalesce(
                                Concat(
                                    ForAll(
                                        Table(ParseJSON(varDefaultApprovalAppSettings.'Default Notifications')),
                                        {Mail: Text(Value.PersonaRole)}
                                    ),
                                    Mail,
                                    Char(13)
                                ),
                                "None"
                            )
                        },
                        Switch(
                            varDefaultApprovalAppSettings.'Approval Mode',
                            'Approval Mode'.'Formal Approval',
                            $"Portfolio Manager:{Char(13)}{varPortfolioManager}{Char(13)}{Char(13)}Contributors:{Char(13)}{varDefaultContributors}{Char(13)}{Char(13)}Approvers:{Char(13)}{varDefaultApprovers}{Char(13)}{Char(13)}Notifications:{Char(13)}{varDefaultNotifications}",
