With(
    {
        varDefaultApprovalMode: LookUp(
            'Project Default Approvals',
            'Project Default Approvals' = ThisItem.Gate
        ),
        varDefaultApproval: Table(
            ParseJSON(
                LookUp(
                    'Project State Trackings',
                    'Project State Tracking' = GUID(ThisItem.State.ID),
                    'Last Triggered Approval Personas'
                )
            )
        ),
        varProjectStateTracking: LookUp(
            'Project State Trackings',
            Project.Project = gblRecordSelectedProject.Project && 'Cluster State'.'Project State' = LookUp(
                'Project Default Approvals',
                'Project Default Approvals' = ThisItem.Gate
            ).'Cluster State'.'Project State'
        ),
        varProjectStateTrackingApproval: LookUp(
            'Project State Trackings',
            Project.Project = gblRecordSelectedProject.Project && 'Cluster State'.'Project State' = LookUp(
                'Project Default Approvals',
                'Project Default Approvals' = ThisItem.Gate
            ).'Cluster State'.'Project State'
        ).FlowApprovalId
    },
    With(
        {
            varApprovalResponses: AddColumns(
                Filter(
                    'Approval Responses',
                    'Approval Id Index' = varProjectStateTrackingApproval
                ),
                AzureObjId,
                Text('Owning User'.'Primary Email')
            ),
            varPortfolioManager: Coalesce(
                Concat(
                    ForAll(
                        varDefaultApproval,
                        {Mail: Value.PortfolioManager}
                    ),
                    Mail,
                    Char(13)
                ),
                "None"
            ),
            varDefaultApprovers: ForAll(
                Split(
                    Concat(
                        ForAll(
                            varDefaultApproval,
                            {Mail: Value.Approvers}
                        ),
                        Mail
                    ),
                    Char(13)
                ),
                {Mail: Trim(Value)}
            )
        },
        If(
            varDefaultApprovalMode.'Approval Mode' <> 'Approval Mode'.'Only Notifications',
            $"Pending:{Char(13) & Char(13) & If(
                varProjectStateTracking.'Cluster Step State' = 'Approval Cluster Step State'.'Portfolio Manager',
                "Portfolio Manager:" & Char(13) & varPortfolioManager & Char(13) & Char(13)
            )}Approvers:{Char(13)}{Concat(
                Filter(
                    varDefaultApprovers,
                    IsBlank(
                        LookUp(
                            varApprovalResponses,
                            AzureObjId = Mail
                        )
                    )
                ),
                Mail,
                Char(13)
            )}"
        )
    )
)

